// Builds the classification prompt for Claude.
// TODO: adjust category descriptions if your real inbox needs differ.
const fromEmail = $json.from_email || '';
const subject = $json.subject || '';
const body = $json.body || '';

const prompt = `You are classifying an inbound email to a real estate agency so it can be routed correctly.

Categories:
- faq_answerable: A factual question answerable from the agency's own knowledge base (hours, general process, pricing structure, areas served, generic property-type questions). NOT this category if it references a specific property, listing, or requires looking up live data.
- lead_inquiry: A new or existing prospect expressing interest in buying/selling/renting, asking about a specific property, or requesting more information that isn't a simple FAQ.
- complaint: Expresses dissatisfaction, frustration, or a problem with service already received.
- scheduling: Explicitly asking to book, reschedule, or cancel a viewing/appointment.
- spam: Marketing, phishing, irrelevant solicitation, automated notifications not requiring a business reply.
- other: Doesn't clearly fit any category above.

Email:
From: ${fromEmail}
Subject: ${subject}
Body:
${body}

Respond with ONLY valid JSON, no other text:
{
  "category": "<one of the 6 categories above>",
  "confidence": <float 0.0-1.0>,
  "reasoning": "<one sentence why>"
}`;

return [{ json: { ...$json, prompt } }];

// Parses and validates Claude's classification JSON.
// TODO: add stricter error handling / retry-on-parse-failure if you see bad output in testing.
const ALLOWED = ['faq_answerable','lead_inquiry','complaint','scheduling','spam','other'];

let raw = '';
try {
  raw = $json.content[0].text;
} catch (e) {
  throw new Error('Unexpected Claude response shape: ' + JSON.stringify($json));
}

// Strip any accidental markdown fences before parsing.
const cleaned = raw.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse classification JSON: ' + cleaned);
}

if (!ALLOWED.includes(parsed.category)) {
  parsed.category = 'other';
}

let confidence = Number(parsed.confidence);
if (isNaN(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

return [{
  json: {
    category: parsed.category,
    confidence,
    reasoning: parsed.reasoning || ''
  }
}];
